public class InnerCapacityProviderManagedInstancesProviderFactory(Action<Humidifier.ECS.CapacityProviderTypes.ManagedInstancesProvider> factoryAction = null) : SubResourceFactory<Humidifier.ECS.CapacityProviderTypes.ManagedInstancesProvider>
{

    internal InnerCapacityProviderAutoRepairConfigurationFactory AutoRepairConfigurationFactory { get; set; }

    internal InnerCapacityProviderInfrastructureOptimizationFactory InfrastructureOptimizationFactory { get; set; }

    internal InnerCapacityProviderInstanceLaunchTemplateFactory InstanceLaunchTemplateFactory { get; set; }

    protected override Humidifier.ECS.CapacityProviderTypes.ManagedInstancesProvider Create()
    {
        var managedInstancesProviderResult = CreateManagedInstancesProvider();
        factoryAction?.Invoke(managedInstancesProviderResult);

        return managedInstancesProviderResult;
    }

    private Humidifier.ECS.CapacityProviderTypes.ManagedInstancesProvider CreateManagedInstancesProvider()
    {
        var managedInstancesProviderResult = new Humidifier.ECS.CapacityProviderTypes.ManagedInstancesProvider();

        return managedInstancesProviderResult;
    }
    public override void CreateChildren(Humidifier.ECS.CapacityProviderTypes.ManagedInstancesProvider result)
    {
        base.CreateChildren(result);

        result.AutoRepairConfiguration ??= AutoRepairConfigurationFactory?.Build();
        result.InfrastructureOptimization ??= InfrastructureOptimizationFactory?.Build();
        result.InstanceLaunchTemplate ??= InstanceLaunchTemplateFactory?.Build();
    }

} // End Of Class

